                }
            }
            for exdate in &incoming.exdates {
                changes.push(match exdate {
                    crate::ics::NormalizedDateValue::Timed(dt) => RecurringExceptionChange::DeleteTimed(dt.timestamp()),
                    crate::ics::NormalizedDateValue::AllDay(date) => RecurringExceptionChange::DeleteAllDay(date.format("%Y-%m-%d").to_string()),
                });
            }
            applied_recurring_exceptions = true;
            event_service.replace_recurring_series(session.user_id, false, calendar.calendar_id, resource.event_id, RecurringSeriesChange { expected_version: event.version, event: mutation, exceptions: changes }).await
        } else {
            event_service.update(session.user_id, false, calendar.calendar_id, resource.event_id, EventChange { expected_version: event.version, target_calendar_id: calendar.calendar_id, event: mutation }).await
        };
        match result {
            Ok(projection) => projection,
            Err(EventServiceError::Conflict { .. }) => {
                return (StatusCode::PRECONDITION_FAILED, "precondition failed").into_response();
            }
            Err(EventServiceError::NotFound) => return dav_resource_not_found(),
            Err(EventServiceError::ReadOnly) => return dav_resource_not_found(),
            Err(_) => return dav_server_error(),
        }
    };

    if is_existing_recurring && incoming.recurrence_id.is_none() && !applied_recurring_exceptions {
        let mut expected_version = projection.version.unwrap_or(event.version + 1);
        for exception in exceptions {
