                    start_utc: starts_at.timestamp(), end_utc: ends_at.timestamp(),
                    timezone: timezone.clone().unwrap_or_else(|| "UTC".to_owned()),
                },
                crate::ics::NormalizedTiming::AllDay { start_date, end_date } => EventTiming::AllDay {
                    start_date: start_date.format("%Y-%m-%d").to_string(),
                    end_date: end_date.format("%Y-%m-%d").to_string(),
                },
            };
            let exception_status = match exception.status.as_deref() {
                Some("TENTATIVE") => EventStatus::Tentative,
                Some("CANCELLED") => EventStatus::Cancelled,
                _ => EventStatus::Confirmed,
            };
            let result = match exception.recurrence_id.as_ref().expect("filtered above") {
                crate::ics::NormalizedDateValue::Timed(dt) => event_service.update_occurrence(
                    session.user_id, false, calendar.calendar_id, resource.event_id,
                    crate::event::OccurrenceChange {
                        recurrence_id: dt.timestamp(), expected_version,
                        event: EventMutation { title: exception.summary.clone(), description: exception.description.clone(), location: exception.location.clone(), status: exception_status, timing: exception_timing },
                    },
                ).await,
                crate::ics::NormalizedDateValue::AllDay(date) => event_service.update_all_day_occurrence(
                    session.user_id, false, calendar.calendar_id, resource.event_id,
                    crate::event::AllDayOccurrenceChange {
                        recurrence_date: date.format("%Y-%m-%d").to_string(), expected_version,
                        event: EventMutation { title: exception.summary.clone(), description: exception.description.clone(), location: exception.location.clone(), status: exception_status, timing: exception_timing },
                    },
                ).await,
            };
            match result {
                Ok(next_projection) => {
                    expected_version = next_projection.version.unwrap_or(expected_version);
                    projection = next_projection;
                }
                Err(EventServiceError::Conflict { .. }) => {
                    return (StatusCode::PRECONDITION_FAILED, "precondition failed").into_response();
                }
                Err(EventServiceError::NotFound | EventServiceError::ReadOnly) => return dav_resource_not_found(),
                Err(_) => return dav_server_error(),
            }
        }
        for exdate in &incoming.exdates {
            let result = match exdate {
                crate::ics::NormalizedDateValue::Timed(dt) => event_service
                    .delete_occurrence(
                        session.user_id,
