    accounts: &CaldavAccountService,
    principal_id: &str,
    calendar_id: i64,
    resource_name: &str,
    auth: (&str, &str),
) -> String {
    let uri = format!("/dav/calendars/{principal_id}/{calendar_id}/{resource_name}.ics");
    let (_, headers, _) = request(
        build_caldav_router(accounts.clone()),
        Method::GET,
        &uri,
        Some(auth),
    )
    .await;
    headers
        .get(header::ETAG)
        .unwrap()
        .to_str()
        .unwrap()
        .to_owned()
}

